mapper.select:
SELECT id, org_id, invited_email, invited_user_id, inviter_id, role, token, status, expires_at, created_at
FROM sys_org_invitation
WHERE id = #{id}

SELECT id, org_id, invited_email, invited_user_id, inviter_id, role, token, status, expires_at, created_at
FROM sys_org_invitation
WHERE token = #{token}

mapper.insert:
INSERT INTO sys_org_invitation (
    org_id, invited_email, invited_user_id, inviter_id, role, token, status, expires_at, created_at
) VALUES (
    #{orgId}, #{invitedEmail}, #{invitedUserId}, #{inviterId}, #{role}, #{token}, #{status}, #{expiresAt}, NOW()
)

mapper.update:
UPDATE sys_org_invitation
SET status = #{status}
WHERE id = #{id}
